#!/usr/bin/env bash
# Build a review packet from a committed range. The packet is intentionally
# generated by the harness, not by the reviewer, so the reviewer never has to
# reconstruct the diff or trust a moving working tree.

set -euo pipefail

usage() {
  cat <<'EOF'
usage: scripts/review-packet.sh <base-ref> <head-ref> [options]

options:
  --out <dir>       output directory (default: artifacts/review/<base>..<head>)
  --verify <cmd>    verification command the reviewer should run; repeatable
  --doc <path>      contract/doc/skill path the reviewer must check; repeatable
  --help            show this help

The packet contains packet.md, diff.patch, changed-files.txt and log.txt.
Output is written under artifacts/ by default, which is gitignored.
EOF
}

if [ "${1:-}" = "--help" ] || [ "${1:-}" = "-h" ]; then
  usage
  exit 0
fi

if [ "$#" -lt 2 ]; then
  usage >&2
  exit 2
fi

base_ref=$1
head_ref=$2
shift 2

out_dir=""
verify_commands=()
doc_paths=()

while [ "$#" -gt 0 ]; do
  case "$1" in
    --out)
      [ "$#" -ge 2 ] || { echo "missing value for --out" >&2; exit 2; }
      out_dir=$2
      shift 2
      ;;
    --verify)
      [ "$#" -ge 2 ] || { echo "missing value for --verify" >&2; exit 2; }
      verify_commands+=("$2")
      shift 2
      ;;
    --doc)
      [ "$#" -ge 2 ] || { echo "missing value for --doc" >&2; exit 2; }
      doc_paths+=("$2")
      shift 2
      ;;
    --help|-h)
      usage
      exit 0
      ;;
    *)
      echo "unknown argument: $1" >&2
      usage >&2
      exit 2
      ;;
  esac
done

if ! git rev-parse --is-inside-work-tree >/dev/null 2>&1; then
  echo "not inside a git worktree" >&2
  exit 2
fi

repo_root=$(git rev-parse --show-toplevel)
cd "$repo_root"

# --end-of-options prevents a ref supplied by an operator from being parsed as
# an option. The commit suffix resolves annotated tags as well.
base_sha=$(git rev-parse --verify --end-of-options "${base_ref}^{commit}")
head_sha=$(git rev-parse --verify --end-of-options "${head_ref}^{commit}")
base_short=${base_sha:0:12}
head_short=${head_sha:0:12}

if [ -z "$out_dir" ]; then
  out_dir="artifacts/review/${base_short}..${head_short}"
fi

mkdir -p "$out_dir"
packet_path="$out_dir/packet.md"
diff_path="$out_dir/diff.patch"
files_path="$out_dir/changed-files.txt"
log_path="$out_dir/log.txt"
status_path="$out_dir/status.txt"

git diff --no-ext-diff --binary "$base_sha" "$head_sha" >"$diff_path"
git diff --no-ext-diff --name-status "$base_sha" "$head_sha" >"$files_path"
git log --oneline --no-decorate "$base_sha..$head_sha" >"$log_path"
git status --porcelain >"$status_path"

working_tree="clean"
if [ -s "$status_path" ]; then
  working_tree="dirty (see status.txt)"
fi

diff_stat=$(git diff --no-ext-diff --stat "$base_sha" "$head_sha")
changed_count=$(wc -l <"$files_path" | tr -d ' ')

{
  printf '# Review packet\n\n'
  printf -- '- Repository: `%s`\n' "$repo_root"
  printf -- '- Base: `%s` (`%s`)\n' "$base_ref" "$base_sha"
  printf -- '- Head: `%s` (`%s`)\n' "$head_ref" "$head_sha"
  printf -- '- Working tree: %s\n' "$working_tree"
  printf -- '- Diff: `%s`\n' "$diff_path"
  printf -- '- Changed files: `%s` (%s entries)\n' "$files_path" "$changed_count"
  printf -- '- Commit log: `%s`\n\n' "$log_path"
  printf '## Verification commands supplied\n\n'
  if [ "${#verify_commands[@]}" -eq 0 ]; then
    printf '_None supplied._\n'
  else
    printf '```text\n'
    printf '%s\n' "${verify_commands[@]}"
    printf '```\n'
  fi
  printf '\n## Contract/doc/skill paths\n\n'
  if [ "${#doc_paths[@]}" -eq 0 ]; then
    printf '_None supplied._\n'
  else
    printf '%s\n' "${doc_paths[@]}" | sed 's/^/- `/; s/$/`/'
  fi
  printf '\n## Diff stat\n\n```text\n%s\n```\n\n' "$diff_stat"
  printf '## Reviewer contract\n\n'
  printf 'Read `diff.patch`, `changed-files.txt`, the commit log and the surrounding code.\n'
  printf 'Apply the code-review skill. Detection comes first; do not treat a passing\n'
  printf 'suite as evidence of soundness. If the shell is available, run the supplied\n'
  printf 'commands only after forming findings; otherwise mark them as not run.\n\n'
  printf 'Return exactly one JSON object (fenced as ```json) with this shape:\n\n'
  printf '```json\n'
  printf '{\n'
  printf '  "verdict": "ok | changes_required | blocked",\n'
  printf '  "diffReviewed": true,\n'
  printf '  "findings": [\n'
  printf '    {\n'
  printf '      "severity": "P0 | P1 | P2",\n'
  printf '      "kind": "correctness | wiring | concurrency | protocol | limits | performance | trust | docs",\n'
  printf '      "path": "src/Example.cs",\n'
  printf '      "line": 42,\n'
  printf '      "evidence": "VERIFIED | CODE-READING",\n'
  printf '      "summary": "what is wrong",\n'
  printf '      "fix": "smallest safe fix"\n'
  printf '    }\n'
  printf '  ],\n'
  printf '  "notExamined": ["surface not reviewed"],\n'
  printf '  "testsRun": ["command and observed result"]\n'
  printf '}\n'
  printf '```\n\n'
  printf 'A missing or unreadable diff is `verdict: "blocked"`, never `"ok"`.\n'
  printf 'Documented CLI/help/skill examples that do not work are P1 wiring findings.\n'
  printf 'Read-only: do not edit files, create worktrees, or start/stop services.\n'
} >"$packet_path"

printf 'packet=%s\n' "$packet_path"
printf 'diff=%s\n' "$diff_path"
printf 'changed_files=%s\n' "$files_path"
printf 'log=%s\n' "$log_path"
